refentry.refsect1:
&reftitle.returnvalues;

 Returns &true; if the watcher is registered with a context, &false;
 otherwise.

  &reftitle.examples;

   Io\Poll\Watcher::isActive example


<?php
use Io\Poll\Context;
use Io\Poll\Event;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();

$watcher = $context->add(new StreamPollHandle($reader), [Event::Read]);
var_dump($watcher->isActive());
$watcher->remove();
var_dump($watcher->isActive());

// Closing the stream deactivates its watchers.
$watcher = $context->add(new StreamPollHandle($writer), [Event::Write]);
fclose($writer);
var_dump($watcher->isActive());


   &example.outputs;


bool(true)
bool(false)
bool(false)
